// Return one n8n item per lead. Expected labels and score ranges are intentionally excluded.
return leads.map((lead) => ({
  json: {
    name: lead.name,
    email: lead.email,
    phone: lead.phone,
    service: lead.service,
    message: lead.message,
  },
}));
